'use strict';
// Purpose-built IDE controls; isolated native mock, no real progress or backend writes.
const fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),fixture=path.resolve(root,'../.rural-quiz-runtime/native-visual-review'),qa=path.join(root,'qa/mascot-context-20261020');
const themes=(process.argv[2]||'ecology,culture,red,industry').split(','),events=fs.existsSync(path.join(qa,'native-events.json'))?JSON.parse(fs.readFileSync(path.join(qa,'native-events.json'))):[];
async function call(tool,args){return new Promise((resolve,reject)=>{const child=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',fixture,...args]);let out='',err='';const timer=setTimeout(()=>{child.kill();reject(Error(tool+' timeout'));},45000);child.stdout.on('data',b=>out+=b);child.stderr.on('data',b=>err+=b);child.on('error',reject);child.on('close',code=>{clearTimeout(timer);let r;try{r=JSON.parse(out.slice(out.indexOf('{')));}catch{return reject(Error(err||out));}events.push({tool,args,ok:r.ok,result:r.result||r.message});fs.writeFileSync(path.join(qa,'native-events.json'),JSON.stringify(events,null,2)+'\n');if(code||!r.ok||r.result?.success===false)reject(Error(tool+': '+(r.message||r.result?.error)));else resolve(r.result);});});}
const scenes=[['profile','home&route=profile','.profile-avatar'],['quiz','quiz','.quest-companion'],['revive','revive','.revive-companion'],['locked','locked','.rest-companion'],['result','result','.result-companion'],['certificate','certificate','.certificate-companion']];
module.exports={call,qa};
if(require.main===module)(async()=>{for(const theme of themes)for(const [scene,query,selector] of scenes.filter(s=>!process.argv[3]||process.argv[3].split(',').includes(s[0]))){await call('simulator_open_page',['--page','pages/game/index','--query','theme='+theme+'&review=1&controls=0&scenario='+query]);await call('simulator_screenshot',['--path',path.join(qa,theme+'-'+scene+'.png'),'--optimize','false','--wait-for-selector',selector]);console.log('Captured '+theme+' '+scene);}})().catch(e=>{console.error(e);process.exitCode=1;});
